# Fy1 effekt och verkningsgrad (omr effekt), omskrivet för hand 2026-11-17.
FIG = '<span class="fig">[F1]</span>'


def p(*s):
    return ''.join(f'<p>{x}</p>' for x in s)


def kort(ctx, fraga):
    return {'t': p(ctx, fraga), 'f': fraga}


def enkel(text):
    """Delkort utan intro där t = <p>text</p> och fraga = text."""
    return {'t': p(text), 'f': text}


